package local.morph.palettecheck;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.lang.reflect.*;
public final class PhonePaletteInstrumentation extends Instrumentation{
 Activity player;Object field(String key)throws Exception{Field f=player.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(player);}void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{
 player=startActivitySync(new Intent().setClassName(getTargetContext().getPackageName(),"local.tvmorph.tv.PlayerActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("phone",true).putExtra("url","http://10.0.2.2:8788/output/fixture.mp4").putExtra("name","Local mobile palette verification").putExtra("itemKind","vod").putExtra("itemId","palette-fixture").putExtra("live",false));
 long until=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<until&&!Boolean.TRUE.equals(field("prepared")))Thread.sleep(50);check(Boolean.TRUE.equals(field("prepared")),"Owned fixture prepares");
 Class<?> palette=Class.forName("local.tvmorph.tv.PlayerPalette",true,getTargetContext().getClassLoader());Method accent=palette.getDeclaredMethod("accent",Context.class),text=palette.getDeclaredMethod("text",Context.class),surface=palette.getDeclaredMethod("surface",Context.class);accent.setAccessible(true);text.setAccessible(true);surface.setAccessible(true);
 check(((Integer)accent.invoke(null,player))==0xff2463eb,"Phone accent is cobalt");check(((Integer)text.invoke(null,player))==0xfff7f9ff,"Phone text is white");check(((Integer)surface.invoke(null,player))==0xff263a55,"Phone surface is navy slate");
 Method dock=player.getClass().getDeclaredMethod("dockDraw");dock.setAccessible(true);android.graphics.drawable.Drawable glass=(android.graphics.drawable.Drawable)dock.invoke(player);Bitmap sample=Bitmap.createBitmap(100,100,Bitmap.Config.ARGB_8888);glass.setBounds(0,0,100,100);glass.draw(new Canvas(sample));int opacity=Color.alpha(sample.getPixel(50,50));check(opacity>=210&&opacity<235,"Phone dock is translucent and retains a readable navy backing");sample.recycle();
 Class<?> browser=Class.forName("local.tvmorph.tv.LiveChannelBrowser",true,getTargetContext().getClassLoader());Constructor<?> ctor=browser.getDeclaredConstructor(player.getClass());ctor.setAccessible(true);Object side=ctor.newInstance(player);Method bg=browser.getDeclaredMethod("background",boolean.class);bg.setAccessible(true);android.graphics.drawable.Drawable panel=(android.graphics.drawable.Drawable)bg.invoke(side,false);Bitmap panelSample=Bitmap.createBitmap(100,100,Bitmap.Config.ARGB_8888);panel.setBounds(0,0,100,100);panel.draw(new Canvas(panelSample));check(Color.alpha(panelSample.getPixel(50,50))==222,"Phone categories panel is translucent");panelSample.recycle();
 runOnMainSync(()->{try{Method show=player.getClass().getDeclaredMethod("show");show.setAccessible(true);show.invoke(player);check(((TextView)field("elapsed")).getCurrentTextColor()==0xfff7f9ff,"Timeline text is white");LinearLayout row=(LinearLayout)field("actionRow");boolean found=false;for(int i=0;i<row.getChildCount();i++){View b=row.getChildAt(i);if(!(b instanceof Button))continue;Field primary=b.getClass().getDeclaredField("main");primary.setAccessible(true);if(primary.getBoolean(b)){Bitmap bm=Bitmap.createBitmap(b.getWidth(),b.getHeight(),Bitmap.Config.ARGB_8888);b.draw(new Canvas(bm));check(bm.getPixel(bm.getWidth()/2,bm.getHeight()/5)==0xff2463eb,"Primary play button is cobalt");bm.recycle();found=true;break;}}check(found,"Primary play control exists");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
 Bitmap screenshot=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream file=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"phone-player-pearl.png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,file);}screenshot.recycle();
 Field mode=player.getClass().getDeclaredField("phoneMode");mode.setAccessible(true);runOnMainSync(()->{try{mode.setBoolean(player,false);check(((Integer)text.invoke(null,player))==0xfff7f9ff,"TV keeps its original light text");mode.setBoolean(player,true);}catch(Exception e){throw new RuntimeException(e);}});
 out.putString("result","PASS: owned video prepares; phone translucent pearl dock and categories panel, white text, cobalt seek/play controls; original TV text retained.");runOnMainSync(()->player.finish());finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));if(player!=null)runOnMainSync(()->player.finish());finish(Activity.RESULT_CANCELED,out);}}
}
